package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.List;
import org.jsoup.Document;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.*;
import org.jsoup.nodes.DocumentType;
import org.jsoup.parser.Tag;
import org.junit.*;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

@RunWith(JUnit4.class)
public class Cleaner_clean_TriageGen0Test {

    private Cleaner cleaner;

    @Before
    public void setup() {
        cleaner = new Cleaner(new Whitelist());
    }

    @Test
    public void clean_NullDirtyDocument() {
        // Given
        Document dirtyDocument = null;

        // When
        Document clean = cleaner.clean(dirtyDocument);

        // Then
        assertNull(clean);
    }

    @Test
    public void clean_EmptyDirtyDocument() {
        // Given
        Document dirtyDocument = Document.createShell("http://example.com");

        // When
        Document clean = cleaner.clean(dirtyDocument);

        // Then
        assertEquals(dirtyDocument, clean);
    }

    @Test
    public void clean_SimpleDirtyDocument() {
        // Given
        Document dirtyDocument = Document.createShell("http://example.com")
                .appendChild("Hello, World!");

        // When
        Document clean = cleaner.clean(dirtyDocument);

        // Then
        assertEquals(dirtyDocument, clean);
    }

    @Test
    public void clean_SimpleDirtyDocumentWithImg() {
        // Given
        Document dirtyDocument = Document.createShell("http://example.com")
                .appendChild("Hello, World!")
                .appendChild("<img src=\"image.jpg\" />");

        // When
        Document clean = cleaner.clean(dirtyDocument);

        // Then
        assertEquals(dirtyDocument, clean);
    }

    @Test
    public void clean_SimpleDirtyDocumentWithComment() {
        // Given
        Document dirtyDocument = Document.createShell("http://example.com")
                .appendChild("Hello, World!")
                .appendChild("<!-- Comment -->");

        // When
        Document clean = cleaner.clean(dirtyDocument);

        // Then
        assertEquals(dirtyDocument, clean);
    }

    @Test
    public void clean_SimpleDirtyDocumentWithScript() {
        // Given
        Document dirtyDocument = Document.createShell("http://example.com")
                .appendChild("Hello, World!")
                .appendChild("<script>alert('Hello World!');</script>");

        // When
        Document clean = cleaner.clean(dirtyDocument);

        // Then
        assertEquals(dirtyDocument, clean);
    }

    @Test
    public void clean_SimpleDirtyDocumentWithStyle() {
        // Given
        Document dirtyDocument = Document.createShell("http://example.com")
                .appendChild("Hello, World!")
                .appendChild("<style>body { background-color: #f2f2f2; }</style>");

        // When
        Document clean = cleaner.clean(dirtyDocument);

        // Then
        assertEquals(dirtyDocument, clean);
    }

    @Test
    public void clean_SimpleDirtyDocumentWithIFrame() {
        // Given
        Document dirtyDocument = Document.createShell("http://example.com")
                .appendChild("Hello, World!")
                .appendChild("<iframe src=\"http://example2.com\"></iframe>");

        // When
        Document clean = cleaner.clean(dirtyDocument);

        // Then
        assertEquals(dirtyDocument, clean);
    }

    @Test
    public void clean_SimpleDirtyDocumentWithAnchor() {
        // Given
        Document dirtyDocument = Document.createShell("http://example.com")
                .appendChild("Hello, World!")
                .appendChild("<a href=\"http://example2.com\">Link</a>");

        // When
        Document clean = cleaner.clean(dirtyDocument);

        // Then
        assertEquals(dirtyDocument, clean);
    }

    @Test
    public void clean_SimpleDirtyDocumentWithMeta() {
        // Given
        Document dirtyDocument = Document.createShell("http://example.com")
                .appendChild("Hello, World!")
                .appendChild("<meta name=\"description\" content=\"Hello World!\" />");

        // When
        Document clean = cleaner.clean(dirtyDocument);

        // Then
        assertEquals(dirtyDocument, clean);
    }

    @Test
    public void clean_SimpleDirtyDocumentWithTitle() {
        // Given
        Document dirtyDocument = Document.createShell("http://example.com")
                .appendChild("Hello, World!")
                .appendChild("<title>Hello World!</title>");

        // When
        Document clean = cleaner.clean(dirtyDocument);

        // Then
        assertEquals(dirtyDocument, clean);
    }

    @Test
    public void clean_SimpleDirtyDocumentWithDocumentType() {
        // Given
        Document dirtyDocument = Document.createShell("http://example.com")
                .appendChild("Hello, World!")
                .appendChild("<!DOCTYPE html PUBLIC \"-//W3C//DTD HTML 4.01 Transitional//EN\" \"http://www.w3.org/TR/html4/loose.dtd\">");

        // When
        Document clean = cleaner.clean(dirtyDocument);

        // Then
        assertEquals(dirtyDocument, clean);
    }
}
